<?php
namespace Modules\ComplianceIQ\Jobs;
use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Modules\ComplianceIQ\Entities\ComplianceReport;use Modules\ComplianceIQ\Services\Compliance\ComplianceReportService;use Modules\TitanZeroAssurance\Services\ExecutionContextStore;use Modules\TitanZeroAssurance\ValueObjects\CompanyExecutionContext;
class GenerateComplianceSummary implements ShouldQueue {use Dispatchable,Queueable;public function __construct(public int $companyId,public int $reportId){}public function handle(ComplianceReportService $reports,ExecutionContextStore $contexts):void {$contexts->runWith(new CompanyExecutionContext($this->companyId,'system','compliance-report'),function()use($reports){$r=ComplianceReport::query()->where('company_id',$this->companyId)->find($this->reportId);if(!$r)return;$summary=$reports->build($r);$r->update(['summary'=>$summary,'integrity_root'=>$summary['integrity']['integrity_root']]);});}}
